let lead = {};
try {
  const inputData = $input.first().json.body.message?.toolCalls?.[0]?.function?.args?.datos_lead || $input.first().json.body.datos_lead;
  lead = typeof inputData === 'string' ? JSON.parse(inputData) : inputData;
} catch (e) {
  console.error("Error parsing datos_lead:", e);
}

const flatArgs = $input.first().json.body.message?.toolCalls?.[0]?.function?.args || {};
const motivoText = lead?.motivo || lead?.motivo_consulta || lead?.notas || lead?.observaciones || lead?.consulta || flatArgs.motivo || flatArgs.motivo_consulta || flatArgs.observaciones || flatArgs.notas || 'No especificado';

// Dynamic specialty detection from motive
let especialidad = lead?.specialty || lead?.especialidad || flatArgs.specialty || flatArgs.especialidad || '';
if (!especialidad) {
  const motivosLower = motivoText.toLowerCase();
  if (motivosLower.includes('sensorial') || motivosLower.includes('motor') || motivosLower.includes('ocupacional') || motivosLower.includes('mano') || motivosLower.includes('escribir') || motivosLower.includes('vestirse') || motivosLower.includes('coordinacion') || motivosLower.includes('coordinación')) {
    especialidad = 'Terapia Ocupacional';
  } else if (motivosLower.includes('psicolog') || motivosLower.includes('emocion') || motivosLower.includes('comportamiento') || motivosLower.includes('ansiedad') || motivosLower.includes('rabietas') || motivosLower.includes('miedo')) {
    especialidad = 'Psicología Infantil';
  } else if (motivosLower.includes('neuro') || motivosLower.includes('atencion') || motivosLower.includes('atención') || motivosLower.includes('memoria')) {
    especialidad = 'Neuropsicología';
  } else if (motivosLower.includes('temprana') || motivosLower.includes('estimul') || motivosLower.includes('bebe') || motivosLower.includes('bebé')) {
    especialidad = 'Atención Temprana';
  } else {
    especialidad = 'Logopedia'; // Default fallback
  }
}

return [{
  json: {
    nombre_padre: lead?.nombre_padre || flatArgs.nombre_padre || 'Interesado',
    nombre_niño: lead?.nombre_niño || lead?.nombre_nino || flatArgs.nombre_niño || flatArgs.nombre_nino || 'Paciente Nuevo',
    telefono: lead?.telefono || flatArgs.telefono || flatArgs.telefono_origen || $input.first().json.body.message?.customer?.number || $input.first().json.body.telefono_origen || '',
    motivo: motivoText,
    specialty: especialidad
  }
}];

