const newItems = [];
for (let item of $input.all()) {
  let newItem = JSON.parse(JSON.stringify(item.json));
  try {
    let toolCall = newItem.body?.message?.toolCalls?.[0];
    if (toolCall && toolCall.function && toolCall.function.arguments) {
      let argsStr = toolCall.function.arguments;
      let args = typeof argsStr === 'string' ? JSON.parse(argsStr) : argsStr;

      // Normalizar nombre de terapeuta para base de datos (con tildes correctas)
      if (args.terapeuta) {
        let t = args.terapeuta.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
        t = t.trim();
        if (t.includes("sofia")) args.terapeuta = "Sofía";
        else if (t.includes("angela")) args.terapeuta = "Ángela";
        else if (t.includes("ruth") || t.includes("rut") || t.includes("rus") || t.includes("ruts")) args.terapeuta = "Ruth";
        else if (t.includes("marta")) args.terapeuta = "Marta";
        else if (t.includes("laura")) args.terapeuta = "Laura";
        else if (t.includes("yaiza")) args.terapeuta = "Yaiza";
        else if (t.includes("zoe")) args.terapeuta = "Zoe";
      }

      // Renombramos los argumentos a 'args' para que el Switch lo pueda leer sin alarmas
      toolCall.function.args = args;

      // Subimos la acción al panel principal
      if (!newItem.body) newItem.body = {};
      newItem.body.accion = args.accion;
    }
  } catch (err) {}
  newItems.push({ json: newItem });
}
return newItems;
